script:
// Adds a "Confirm Receipt" action button to the Appointment form for hosts
// once their visitor has been checked in and a badge issued — the only
// other way to confirm receipt is scanning the visitor badge's QR code,
// which isn't practical if the host is just looking at the record itself
// (e.g. checking their appointment list at their desk).
frappe.ui.form.on('Appointment', {
	refresh: function (frm) {
		if (
			frm.doc.workflow_state === 'Visitor Checked In' &&
			frm.doc.custom_visitor_badge &&
			!frm.doc.custom_host_received_time
		) {
			frm.add_custom_button('Confirm Receipt', function () {
				frappe.call({
					method: 'confirm_host_received_by_appointment',
					args: { name: frm.doc.name },
					freeze: true,
					freeze_message: __('Confirming...'),
					callback: function (r) {
						if (r.message && r.message.error) {
							frappe.msgprint(r.message.error);
							return;
						}
						frappe.show_alert({ message: __('Visitor receipt confirmed'), indicator: 'green' });
						frm.reload_doc();
					},
				});
			}).addClass('btn-primary');
		}

		if (frm.doc.custom_host_received_time) {
			frm.dashboard.set_headline_alert(
				'<span class="indicator-pill green">Visitor receipt confirmed at ' +
					frappe.datetime.str_to_user(frm.doc.custom_host_received_time) +
					'</span>',
			);
		}
	},
});

frappe.ui.form.on('Appointment', {
    before_workflow_action: function(frm) {
        var action = frm.selected_workflow_action;

        if (action === 'Reschedule') {
            frappe.dom.unfreeze();
            return new Promise(function(resolve, reject) {
                var host_id = frm.doc.custom_meet_with || '';
                frappe.db.get_value('Employee', host_id, 'employee_name').then(function(r) {
                    var host_display = (r && r.message && r.message.employee_name) ? r.message.employee_name : host_id;
                    var d = new frappe.ui.Dialog({
                        title: 'Reschedule Visit',
                        fields: [
                            {
                                fieldname: 'visitor_info',
                                fieldtype: 'HTML',
                                options: '<div class="alert alert-info" style="margin-bottom:0"><b>' + (frm.doc.customer_name || '') + '</b> is waiting to see <b>' + host_display + '</b></div>'
                            },
                            {
                                label: 'New Date and Time',
                                fieldname: 'new_scheduled_time',
                                fieldtype: 'Datetime',
                                reqd: 1,
                                default: frappe.datetime.now_datetime()
                            },
                            {
                                label: 'Reason for Rescheduling',
                                fieldname: 'reschedule_reason',
                                fieldtype: 'Small Text',
                                reqd: 1
                            }
                        ],
                        size: 'large',
                        primary_action_label: 'Confirm Reschedule',
                        primary_action: function(values) {
                            d.disable_primary_action();
                            frappe.call({
                                method: 'frappe.client.set_value',
                                args: {
                                    doctype: 'Appointment',
                                    name: frm.doc.name,
                                    fieldname: 'scheduled_time',
                                    value: values.new_scheduled_time
                                },
                                async: false
                            });
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: {
                                    doc: {
                                        doctype: 'Comment',
                                        comment_type: 'Comment',
                                        reference_doctype: 'Appointment',
                                        reference_name: frm.doc.name,
                                        content: '<b>Rescheduled by ' + frappe.session.user_fullname + ':</b> ' + values.reschedule_reason + '<br><b>New time:</b> ' + values.new_scheduled_time,
                                        comment_email: frappe.session.user,
                                        comment_by: frappe.session.user_fullname
                                    }
                                },
                                async: false
                            });
                            frm.reload_doc();
                            d.hide();
                            resolve();
                        }
                    });
                    d.show();
                    d.$wrapper.find('.modal-dialog').css('z-index', 1100);
                    d.$wrapper.find('.modal-backdrop').css('z-index', 1099);
                });
            });
        }

        if (action === 'Redirect to Another Host') {
            frappe.dom.unfreeze();
            return new Promise(function(resolve, reject) {
                var host_id = frm.doc.custom_meet_with || '';
                frappe.db.get_value('Employee', host_id, 'employee_name').then(function(r) {
                    var old_host_display = (r && r.message && r.message.employee_name) ? r.message.employee_name : host_id;
                    var d = new frappe.ui.Dialog({
                        title: 'Redirect Visitor to Another Host',
                        fields: [
                            {
                                fieldname: 'visitor_info',
                                fieldtype: 'HTML',
                                options: '<div class="alert alert-warning" style="margin-bottom:0"><b>' + (frm.doc.customer_name || '') + '</b> was scheduled to see <b>' + old_host_display + '</b> who is unavailable.</div>'
                            },
                            {
                                label: 'Redirect to (New Host)',
                                fieldname: 'new_host',
                                fieldtype: 'Link',
                                options: 'Employee',
                                reqd: 1
                            },
                            {
                                label: 'Reason for Redirect',
                                fieldname: 'redirect_reason',
                                fieldtype: 'Small Text',
                                reqd: 1
                            }
                        ],
                        size: 'large',
                        primary_action_label: 'Confirm Redirect',
                        primary_action: function(values) {
                            d.disable_primary_action();
                            // IMPORTANT: do NOT reassign custom_meet_with here. The
                            // "Redirect to Another Host" workflow transition's own
                            // permission condition checks whether the CURRENT
                            // custom_meet_with resolves to the acting user (the
                            // original host). apply_workflow() always re-reads the
                            // doc fresh from the database at the moment the
                            // transition is applied, so if we rewrote
                            // custom_meet_with to the new host here (before the
                            // transition runs), the original host would fail their
                            // own permission check a few hundred milliseconds
                            // later. Stash the new host on frm and do the actual
                            // field/comment update in after_workflow_action,
                            // once the transition has already gone through.
                            frm._pending_redirect = {
                                new_host: values.new_host,
                                redirect_reason: values.redirect_reason,
                                old_host_display: old_host_display
                            };
                            d.hide();
                            resolve();
                        }
                    });
                    d.show();
                    d.$wrapper.find('.modal-dialog').css('z-index', 1100);
                    d.$wrapper.find('.modal-backdrop').css('z-index', 1099);
                });
            });
        }

        if (action === 'Reject Visit') {
            frappe.dom.unfreeze();
            return new Promise(function(resolve, reject) {
                var host_id = frm.doc.custom_meet_with || '';
                frappe.db.get_value('Employee', host_id, 'employee_name').then(function(r) {
                    var host_display = (r && r.message && r.message.employee_name) ? r.message.employee_name : host_id;
                    var d = new frappe.ui.Dialog({
                        title: 'Reject Visit',
                        fields: [
                            {
                                fieldname: 'visitor_info',
                                fieldtype: 'HTML',
                                options: '<div class="alert alert-danger" style="margin-bottom:0"><b>' + (frm.doc.customer_name || '') + '</b> wants to see <b>' + host_display + '</b></div>'
                            },
                            {
                                label: 'Reason for Rejection',
                                fieldname: 'reject_reason',
                                fieldtype: 'Small Text',
                                reqd: 1
                            }
                        ],
                        size: 'large',
                        primary_action_label: 'Confirm Rejection',
                        primary_action: function(values) {
                            d.disable_primary_action();
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: {
                                    doc: {
                                        doctype: 'Comment',
                                        comment_type: 'Comment',
                                        reference_doctype: 'Appointment',
                                        reference_name: frm.doc.name,
                                        content: '<b>Rejected by ' + frappe.session.user_fullname + ':</b> ' + values.reject_reason,
                                        comment_email: frappe.session.user,
                                        comment_by: frappe.session.user_fullname
                                    }
                                },
                                async: false
                            });
                            d.hide();
                            resolve();
                        }
                    });
                    d.show();
                    d.$wrapper.find('.modal-dialog').css('z-index', 1100);
                    d.$wrapper.find('.modal-backdrop').css('z-index', 1099);
                });
            });
        }

        if (action === 'Approve Visit') {
            frm.doc.custom_reporting_status = 'Scheduled';
            frm.dirty();
        }

        if (action === 'Confirm Check In') {
            frm.doc.custom_check_in_time = frappe.datetime.now_datetime();
            frm.doc.custom_reporting_status = 'Checked in';
            frm.dirty();
        }

        if (action === 'Confirm Check Out') {
            frm.doc.custom_check_out_time = frappe.datetime.now_datetime();
            frm.doc.custom_reporting_status = 'Checked out';
            frm.dirty();
        }
    },

    after_workflow_action: function(frm) {
        // Runs once a workflow transition has actually been applied. The
        // "Redirect to Another Host" reassignment is deferred to here (see
        // before_workflow_action) so the transition's own host-permission
        // condition is evaluated against the ORIGINAL host, not the new one.
        if (frm._pending_redirect) {
            var pending = frm._pending_redirect;
            frm._pending_redirect = null;
            frappe.call({
                method: 'frappe.client.set_value',
                args: {
                    doctype: 'Appointment',
                    name: frm.doc.name,
                    fieldname: 'custom_meet_with',
                    value: pending.new_host
                },
                async: false
            });
            frappe.db.get_value('Employee', pending.new_host, 'employee_name').then(function(r2) {
                var new_host_display = (r2 && r2.message && r2.message.employee_name) ? r2.message.employee_name : pending.new_host;
                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        doc: {
                            doctype: 'Comment',
                            comment_type: 'Comment',
                            reference_doctype: 'Appointment',
                            reference_name: frm.doc.name,
                            content: '<b>Redirected by ' + frappe.session.user_fullname + ':</b> ' + pending.redirect_reason + '<br><b>From:</b> ' + pending.old_host_display + ' <b>To:</b> ' + new_host_display,
                            comment_email: frappe.session.user,
                            comment_by: frappe.session.user_fullname
                        }
                    },
                    async: false
                });
                frm.reload_doc();
            });
        }
    },

    refresh: function(frm) {
        var state = frm.doc.workflow_state;
        var is_gate_guard = frappe.user_roles.includes('Gate Guard');
        var is_secretary = frappe.user_roles.includes('Visit Approver');

        if (is_gate_guard && !is_secretary && !frm.is_new()) {
            var gate_editable = ['custom_mode_of_transport', 'custom_vehicles_number_plate', 'custom_vehicles_colour'];
            frm.fields.forEach(function(f) {
                if (!gate_editable.includes(f.df.fieldname) && f.df.fieldtype !== 'Section Break' && f.df.fieldtype !== 'Column Break') {
                    frm.set_df_property(f.df.fieldname, 'read_only', 1);
                }
            });
        }

        if (is_secretary && state === 'Pending Host Review') {
            var secretary_editable = ['custom_meet_with', 'scheduled_time', 'customer_details', 'custom_visitor_type', 'custom_customer'];
            frm.fields.forEach(function(f) {
                if (secretary_editable.includes(f.df.fieldname)) {
                    frm.set_df_property(f.df.fieldname, 'read_only', 0);
                } else if (f.df.fieldtype !== 'Section Break' && f.df.fieldtype !== 'Column Break') {
                    frm.set_df_property(f.df.fieldname, 'read_only', 1);
                }
            });
        }

        if (state === 'Visitor Checked Out') {
            frm.disable_form();
        }

        if (state === 'Visitor Checked In' && frm.doc.custom_check_in_time) {
            var checkin = moment(frm.doc.custom_check_in_time);
            var duration = moment.duration(moment().diff(checkin));
            var hrs = Math.floor(duration.asHours());
            var mins = duration.minutes();
            frm.dashboard.add_indicator('On premises: ' + hrs + 'h ' + mins + 'm', 'blue');
        }

        if (!frm.is_new() && frm.doc.custom_meet_with_wa) {
            frm.add_custom_button(__('Message Host on WhatsApp'), function() {
                var message = (frm.doc.customer_name || 'A visitor') + ' is here to see you for ' +
                    (frm.doc.custom_visit_purpose || 'a visit') + '. (Ref: ' + (frm.doc.custom_wa_link_suffix || frm.doc.name) + ')';
                var url = 'https://wa.me/' + frm.doc.custom_meet_with_wa + '?text=' + encodeURIComponent(message);
                window.open(url, '_blank');
            });
        }
    }
});

// party/appointment_with are core CRM fields this app never uses
// (locked read-only for Gate Guard/Secretary, never touched by the
// mobile app, custom_customer is the real customer-tracking field).
// Both are hardcoded Link fields to Customer in this ERPNext version
// (not a generic party-type selector, despite the label/filter
// implying otherwise) - so any non-blank value that isn't a real
// Customer record name fails link validation on save.
//
// The crash this fixes: opening "New Appointment" from an
// Appointment list view that has (or ever had) an appointment_with
// filter active lets Frappe carry that filter value into the new
// document as a default - e.g. "Customer" or "Lead" (not an actual
// customer name) - which then fails with "Could not find Appointment
// With: Customer" the moment you try to save, before this doctype's
// own Before Save script ever gets a chance to clear it (link
// validation runs before before_insert/before_save in Frappe's
// document lifecycle, so a server-side clear alone can't prevent
// this on a brand new document - it has to happen client-side).
frappe.ui.form.on("Appointment", {
	onload: function (frm) {
		if (frm.is_new()) {
			frm.set_value("appointment_with", null);
			frm.set_value("party", null);
		}
	},
});

frappe.ui.form.on('Incident Report', {
    status: function(frm) {
        if (frm.doc.status === 'Resolved' || frm.doc.status === 'Closed') {
            if (!frm.doc.resolution_datetime) {
                frappe.model.set_value(frm.doctype, frm.docname, 'resolution_datetime', frappe.datetime.now_datetime());
            }
        } else {
            // Clear resolution time if status moved back
            frappe.model.set_value(frm.doctype, frm.docname, 'resolution_datetime', null);
        }
    },

    resolution: function(frm) {
        if (frm.doc.resolution && !frm.doc.status.match(/Resolved|Closed/)) {
            frappe.model.set_value(frm.doctype, frm.docname, 'status', 'Resolved');
        }
    }
});

frappe.ui.form.on('Incident Report', {
    refresh: function(frm) {
        frm.clear_custom_buttons();
        // Fixed vs. the real production version: that one checks
        // frm.doc.workflow_state, a field that does not exist on this
        // doctype anywhere (confirmed against production itself) - so its
        // Resolved/Closed-state buttons never actually behave as intended
        // there. This checks the real field, `status`, instead. Also drops
        // "Pending Closure Review" from the state list below since it was
        // never a real status option here (or on production).
        let state = frm.doc.status;

        // ─── OPEN / IN PROGRESS ───────────────────────────────────────────────
        if (!['Resolved', 'Closed'].includes(state)) {

            // Add Witnesses / Roll Call
            frm.add_custom_button('👥 Add Witnesses / Roll Call', function() {
                let d = new frappe.ui.Dialog({
                    title: '👥 Witnesses & Roll Call',
                    fields: [
                        { fieldtype: 'Section Break', label: 'Person Details' },
                        { fieldname: 'person_name', fieldtype: 'Data', label: 'Full Name', reqd: 1 },
                        { fieldname: 'role_in_incident', fieldtype: 'Select', label: 'Role',
                          options: 'Witness\nVictim\nFirst Responder\nResponsible Person', reqd: 1 },
                        { fieldname: 'contact', fieldtype: 'Data', label: 'Phone / ID (optional)' },
                        { fieldname: 'statement', fieldtype: 'Small Text', label: 'Statement / Notes' }
                    ],
                    primary_action_label: 'Add Person',
                    primary_action: function(values) {
                        let table_map = {
                            'Witness': 'witnesses',
                            'Victim': 'victims',
                            'First Responder': 'responsible_persons',
                            'Responsible Person': 'responsible_persons'
                        };
                        let table = table_map[values.role_in_incident];
                        let row = frappe.model.add_child(frm.doc, table);
                        row.person_name = values.person_name;
                        if (values.contact) row.contact = values.contact;
                        // Fixed: the real Incident Person child doctype's field
                        // is `notes`, not `statement` - the production script
                        // sets a field that doesn't exist on the row at all.
                        if (values.statement) row.notes = values.statement;
                        frappe.call({
                            method: 'frappe.client.save',
                            args: { doc: frm.doc },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({message: '✅ ' + values.person_name + ' added as ' + values.role_in_incident, indicator: 'green'}, 4);
                                    frm.reload_doc();
                                    d.hide();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Incident Actions');

            // Add Evidence
            frm.add_custom_button('📎 Add Photo / Evidence', function() {
                let slots = ['attachment_1','attachment_2','attachment_3','attachment_4'];
                let next_slot = slots.find(f => !frm.doc[f]);
                if (!next_slot) { frappe.msgprint('All 4 attachment slots are used.'); return; }
                let d = new frappe.ui.Dialog({
                    title: '📎 Add Evidence / Photo',
                    fields: [
                        { fieldname: 'file', fieldtype: 'Attach', label: 'Upload File', reqd: 1 }
                    ],
                    primary_action_label: 'Attach',
                    primary_action: function(values) {
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: { doctype: 'Incident Report', name: frm.docname, fieldname: next_slot, value: values.file },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({message: '✅ File attached', indicator: 'green'}, 4);
                                    frm.reload_doc(); d.hide();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Incident Actions');

            // Resolve Incident
            frm.add_custom_button('✅ Resolve Incident', function() {
                let d = new frappe.ui.Dialog({
                    title: '✅ Resolve Incident',
                    fields: [
                        { fieldtype: 'Section Break', label: 'Resolution' },
                        { fieldname: 'resolution', fieldtype: 'Long Text', label: 'How was the incident resolved?', reqd: 1 },
                        { fieldname: 'corrective_actions', fieldtype: 'Long Text', label: 'Corrective Actions (to prevent recurrence)', reqd: 1 },
                        { fieldtype: 'Column Break' },
                        { fieldname: 'resolution_datetime', fieldtype: 'Datetime', label: 'Resolved At', default: frappe.datetime.now_datetime(), reqd: 1 },
                        { fieldtype: 'Section Break', label: '🚑 Casualties' },
                        { fieldname: 'casualties_wounded', fieldtype: 'Int', label: 'Wounded', default: 0 },
                        { fieldname: 'casualties_deceased', fieldtype: 'Int', label: 'Deceased', default: 0 },
                        { fieldtype: 'Column Break' },
                        { fieldname: 'casualties_hospitalized', fieldtype: 'Int', label: 'Hospitalized', default: 0 },
                        { fieldname: 'casualties_unaccounted', fieldtype: 'Int', label: 'Unaccounted', default: 0 },
                        { fieldname: 'casualties_notes', fieldtype: 'Small Text', label: 'Casualty Notes (optional)' }
                    ],
                    primary_action_label: '✅ Mark Resolved',
                    primary_action: function(values) {
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'Incident Report',
                                name: frm.docname,
                                fieldname: {
                                    resolution: values.resolution,
                                    corrective_actions: values.corrective_actions,
                                    resolution_datetime: values.resolution_datetime,
                                    casualties_wounded: values.casualties_wounded,
                                    casualties_deceased: values.casualties_deceased,
                                    casualties_hospitalized: values.casualties_hospitalized,
                                    casualties_unaccounted: values.casualties_unaccounted,
                                    casualties_notes: values.casualties_notes,
                                    status: 'Resolved'
                                }
                            },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({message: '✅ Incident marked as Resolved!', indicator: 'green'}, 5);
                                } else {
                                    frappe.show_alert({message: '⚠️ Could not update status — resolution details saved', indicator: 'orange'}, 5);
                                }
                                d.hide();
                                frm.reload_doc();
                            }
                        });
                    }
                });
                d.show();
            }, 'Incident Actions').addClass('btn-success');
        }

        // ─── RESOLVED STATE ───────────────────────────────────────────────────
        if (state === 'Resolved') {
            frm.add_custom_button('📝 Add Follow-up Note', function() {
                let d = new frappe.ui.Dialog({
                    title: '📝 Add Follow-up Note',
                    fields: [
                        { fieldname: 'note', fieldtype: 'Long Text', label: 'Note / Update', reqd: 1 }
                    ],
                    primary_action_label: 'Save Note',
                    primary_action: function(values) {
                        let existing = frm.doc.remarks || '';
                        let timestamp = frappe.datetime.now_datetime();
                        let updated = existing + (existing ? '\n\n' : '') + '[' + timestamp + '] ' + values.note;
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: { doctype: 'Incident Report', name: frm.docname, fieldname: 'remarks', value: updated },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({message: '✅ Note added', indicator: 'green'}, 4);
                                    frm.reload_doc(); d.hide();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Incident Actions');

            frm.add_custom_button('🔒 Close Incident', function() {
                frappe.confirm('Close this incident? This marks it as fully complete and no further actions will be needed.', function() {
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: { doctype: 'Incident Report', name: frm.docname, fieldname: 'status', value: 'Closed' },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.show_alert({message: '🔒 Incident Closed', indicator: 'blue'}, 5);
                                frm.reload_doc();
                            }
                        }
                    });
                });
            }, 'Incident Actions').addClass('btn-primary');
        }

        // ─── CLOSED STATE ─────────────────────────────────────────────────────
        if (state === 'Closed') {
            frm.dashboard.add_comment('🔒 This incident is closed. No further actions required.', 'blue', true);
        }
    }
});

// Drives Patrol Report's existing "Supervisor Review" fields (status,
// reviewed_by, reviewed_on, supervisor_remarks) with real Desk buttons,
// same pattern as "Incident Report - Resolve Button" — those fields
// already existed on this doctype but had no UI to actually use them
// without hand-editing the raw form.
frappe.ui.form.on('Patrol Report', {
    refresh: function(frm) {
        frm.clear_custom_buttons();
        let status = frm.doc.status;

        if (!['Reviewed', 'Flagged'].includes(status)) {
            frm.add_custom_button('✅ Mark Reviewed', function() {
                let d = new frappe.ui.Dialog({
                    title: '✅ Mark Reviewed',
                    fields: [
                        { fieldname: 'remarks', fieldtype: 'Small Text', label: 'Remarks (optional)' }
                    ],
                    primary_action_label: 'Mark Reviewed',
                    primary_action: function(values) {
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'Patrol Report',
                                name: frm.docname,
                                fieldname: {
                                    status: 'Reviewed',
                                    reviewed_by: frappe.session.user,
                                    reviewed_on: frappe.datetime.now_datetime(),
                                    supervisor_remarks: values.remarks || frm.doc.supervisor_remarks
                                }
                            },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({ message: '✅ Patrol report marked reviewed', indicator: 'green' }, 5);
                                    d.hide();
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Review Actions').addClass('btn-success');

            frm.add_custom_button('🚩 Flag for Follow-up', function() {
                let d = new frappe.ui.Dialog({
                    title: '🚩 Flag for Follow-up',
                    fields: [
                        { fieldname: 'remarks', fieldtype: 'Small Text', label: 'Why is this being flagged?', reqd: 1 }
                    ],
                    primary_action_label: '🚩 Flag',
                    primary_action: function(values) {
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'Patrol Report',
                                name: frm.docname,
                                fieldname: {
                                    status: 'Flagged',
                                    reviewed_by: frappe.session.user,
                                    reviewed_on: frappe.datetime.now_datetime(),
                                    supervisor_remarks: values.remarks
                                }
                            },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({ message: '🚩 Patrol report flagged for follow-up', indicator: 'orange' }, 5);
                                    d.hide();
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Review Actions').addClass('btn-danger');
        }

        if (['Reviewed', 'Flagged'].includes(status)) {
            frm.add_custom_button('📝 Add Follow-up Note', function() {
                let d = new frappe.ui.Dialog({
                    title: '📝 Add Follow-up Note',
                    fields: [
                        { fieldname: 'note', fieldtype: 'Small Text', label: 'Note / Update', reqd: 1 }
                    ],
                    primary_action_label: 'Save Note',
                    primary_action: function(values) {
                        let existing = frm.doc.supervisor_remarks || '';
                        let timestamp = frappe.datetime.now_datetime();
                        let updated = existing + (existing ? '\n\n' : '') + '[' + timestamp + '] ' + values.note;
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: { doctype: 'Patrol Report', name: frm.docname, fieldname: 'supervisor_remarks', value: updated },
                            callback: function(r) {
                                if (!r.exc) {
                                    frappe.show_alert({ message: '✅ Note added', indicator: 'green' }, 4);
                                    d.hide();
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Review Actions');
        }

        if (status === 'Flagged') {
            frm.add_custom_button('✅ Clear Flag (Mark Reviewed)', function() {
                frappe.confirm('Clear the flag on this patrol report and mark it reviewed?', function() {
                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Patrol Report',
                            name: frm.docname,
                            fieldname: { status: 'Reviewed', reviewed_by: frappe.session.user, reviewed_on: frappe.datetime.now_datetime() }
                        },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.show_alert({ message: '✅ Flag cleared', indicator: 'green' }, 5);
                                frm.reload_doc();
                            }
                        }
                    });
                });
            }, 'Review Actions');
        }

        if (status === 'Reviewed') {
            frm.dashboard.set_headline_alert(
                '<span class="indicator-pill green">Reviewed by ' + (frm.doc.reviewed_by || '') +
                    (frm.doc.reviewed_on ? ' on ' + frappe.datetime.str_to_user(frm.doc.reviewed_on) : '') + '</span>'
            );
        }
        if (status === 'Flagged') {
            frm.dashboard.set_headline_alert(
                '<span class="indicator-pill orange">🚩 Flagged by ' + (frm.doc.reviewed_by || '') +
                    (frm.doc.reviewed_on ? ' on ' + frappe.datetime.str_to_user(frm.doc.reviewed_on) : '') + '</span>'
            );
        }
    }
});

// Read-only "Security Check" tab for Delivery Note. Never writes anything
// back to Delivery Note's own record — this only renders whatever the
// gate already recorded in Gate Dispatch Verification (the sole owner of
// that data), same "read-only against the source" principle documented
// at the top of upande_security/api/gate_dispatch.py, just mirrored: here
// Delivery Note is the one reading, not the one being read.
frappe.ui.form.on('Delivery Note', {
	refresh: function (frm) {
		if (frm.is_new()) {
			return;
		}
		frm.set_df_property('security_check_tab', 'hidden', 1);
		frappe.call({
			method: 'upande_security.api.gate_dispatch.get_gate_dispatch_verification_summary',
			args: {
				reference_doctype: 'Delivery Note',
				reference_name: frm.doc.name,
			},
			callback: function (r) {
				var summary = r.message;
				if (!summary) {
					return;
				}
				frm.set_df_property('security_check_tab', 'hidden', 0);
				frm.set_df_property('security_check_html', 'options', render_security_check(summary));
				frm.refresh_field('security_check_html');
			},
		});
	},
});

function render_security_check(summary) {
	var status = summary.gate_verification_status || 'Not Checked';
	var status_color = status === 'Verified' ? 'green' : 'red';
	var guard = frappe.utils.escape_html(summary.gate_verified_by_name || summary.gate_verified_by || '');
	var exit_time = summary.gate_exit_time ? frappe.datetime.str_to_user(summary.gate_exit_time) : '';

	var html = '<div class="security-check-summary">';
	html += '<div style="margin-bottom: 10px;">';
	html += '<span class="indicator-pill ' + status_color + '">' + frappe.utils.escape_html(status) + '</span>';
	html += ' &nbsp; <b>' + __('Verified By') + ':</b> ' + guard;
	if (exit_time) {
		html += ' &nbsp; <b>' + __('Gate Exit Time') + ':</b> ' + exit_time;
	}
	html += '</div>';

	if (status === 'Rejected' && summary.remarks) {
		html += '<div style="margin-bottom: 10px; color: #c0392b;">';
		html += '<b>' + __('Remarks') + ':</b> ' + frappe.utils.escape_html(summary.remarks);
		html += '</div>';
	}

	var checks = summary.item_checks || [];
	if (checks.length) {
		html += '<table class="table table-bordered" style="margin-top: 6px;">';
		html += '<thead><tr>';
		html += '<th>' + __('Item Code') + '</th>';
		html += '<th>' + __('Item Name') + '</th>';
		html += '<th>' + __('UOM') + '</th>';
		html += '<th>' + __('Expected Qty') + '</th>';
		html += '<th>' + __('Actual Qty') + '</th>';
		html += '<th>' + __('Match Status') + '</th>';
		html += '</tr></thead><tbody>';
		checks.forEach(function (row) {
			html += '<tr>';
			html += '<td>' + frappe.utils.escape_html(row.item_code || '') + '</td>';
			html += '<td>' + frappe.utils.escape_html(row.item_name || '') + '</td>';
			html += '<td>' + frappe.utils.escape_html(row.uom || '') + '</td>';
			html += '<td>' + (row.expected_qty != null ? row.expected_qty : '') + '</td>';
			html += '<td>' + (row.actual_qty != null ? row.actual_qty : '') + '</td>';
			html += '<td><span class="indicator-pill ' + match_status_color(row.match_status) + '">' +
				frappe.utils.escape_html(row.match_status || 'Not Checked') + '</span></td>';
			html += '</tr>';
		});
		html += '</tbody></table>';
	}

	html += '</div>';
	return html;
}

function match_status_color(match_status) {
	if (match_status === 'Matches') {
		return 'green';
	}
	if (match_status === 'Short' || match_status === 'Over') {
		return match_status === 'Short' ? 'orange' : 'red';
	}
	return 'grey';
}

